INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-3-11', 'phase-03-lesson-11-binary-search-standard-sorted-array-looku', 'module-5', 11, 'Lesson 5.11: Binary Search: Standard Sorted Array Lookup', 'Prerequisites: Lesson 3.4', 'Prerequisites: Lesson 3.4 | Subtopics: 4 items', 'Systems project application', 160, 4, 870.0, 550.0, '# Lesson 3.11: Binary Search: Standard Sorted Array Lookup

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 3.4
- **Subtopics**:
  - `3.11.1` Binary search requirements: why the underlying collection MUST be sorted before binary search can work.
  - `3.11.2` The three pointers: low, mid, and high.
  - `3.11.3` Avoiding integer overflow: calculating mid as low + (high - low) // 2.
  - `3.11.4` Updating bounds: mid + 1 when target is larger, mid - 1 when target is smaller.
- **Key Failure Modes & Edge Cases**: Forgetting to add or subtract 1 when updating high and low, causing infinite while loops.
- **Verification & Mastery Check**: Implement binary search from memory in pure Python and prove it finds targets in a 1,000,000-item sorted list.
- **Project Application**: StreamBuffer: Fast log index lookup.', '{"solution.py": "# Phase 3 // Lesson 3.11: Binary Search: Standard Sorted Array Lookup\n\ndef solve():\n    \"\"\"\n    Verification: Implement binary search from memory in pure Python and prove it finds targets in a 1,000,000-item so\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.11", "subtopics_count": 4, "verification_criteria": "Implement binary search from memory in pure Python and prove it finds targets in a 1,000,000-item sorted list.", "subtopics": ["3.11.1 Binary search requirements: why the underlying collection MUST be sorted before binary search can work.", "3.11.2 The three pointers: low, mid, and high.", "3.11.3 Avoiding integer overflow: calculating mid as low + (high - low) // 2.", "3.11.4 Updating bounds: mid + 1 when target is larger, mid - 1 when target is smaller."]}'::jsonb, '["Explain how this implementation prevents: Forgetting to add or subtract 1 when updating high and low, causing infinite while loops.", "How does Binary Search: Standard Sorted Array Lookup scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-12', 'phase-03-lesson-12-binary-search-finding-lower-and-upper-bou', 'module-5', 12, 'Lesson 5.12: Binary Search: Finding Lower and Upper Bounds', 'Prerequisites: Lesson 3.11', 'Prerequisites: Lesson 3.11 | Subtopics: 4 items', 'Systems project application', 160, 4, 750.0, 600.0, '# Lesson 3.12: Binary Search: Finding Lower and Upper Bounds

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 3.11
- **Subtopics**:
  - `3.12.1` Handling duplicates in sorted data: finding the first or last occurrence of a target value.
  - `3.12.2` Lower bound: finding the smallest index where array[index] >= target.
  - `3.12.3` Upper bound: finding the smallest index where array[index] > target.
  - `3.12.4` Range queries: counting how many times a value appears in a sorted list using upper_bound - lower_bound.
- **Key Failure Modes & Edge Cases**: Returning the first match found without continuing search toward the left boundary when duplicates exist.
- **Verification & Mastery Check**: Find the starting and ending index of a target value in a sorted array containing duplicate numbers.
- **Project Application**: StreamBuffer: Timestamp boundary searches.', '{"solution.py": "# Phase 3 // Lesson 3.12: Binary Search: Finding Lower and Upper Bounds\n\ndef solve():\n    \"\"\"\n    Verification: Find the starting and ending index of a target value in a sorted array containing duplicate numbers.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.12", "subtopics_count": 4, "verification_criteria": "Find the starting and ending index of a target value in a sorted array containing duplicate numbers.", "subtopics": ["3.12.1 Handling duplicates in sorted data: finding the first or last occurrence of a target value.", "3.12.2 Lower bound: finding the smallest index where array[index] >= target.", "3.12.3 Upper bound: finding the smallest index where array[index] > target.", "3.12.4 Range queries: counting how many times a value appears in a sorted list using upper_bound - lower_bound."]}'::jsonb, '["Explain how this implementation prevents: Returning the first match found without continuing search toward the left boundary when duplicates exist.", "How does Binary Search: Finding Lower and Upper Bounds scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-13', 'phase-03-lesson-13-binary-search-on-solution-space', 'module-5', 13, 'Lesson 5.13: Binary Search on Solution Space', 'Prerequisites: Lesson 3.11', 'Prerequisites: Lesson 3.11 | Subtopics: 4 items', 'Systems project application', 160, 4, 810.0, 650.0, '# Lesson 3.13: Binary Search on Solution Space

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 3.11
- **Subtopics**:
  - `3.13.1` Searching without an array: using binary search to find an optimal answer value directly.
  - `3.13.2` Monotonic condition: if an answer X is possible, all values > X are also possible (or vice versa).
  - `3.13.3` The feasibility function: a helper function that checks can_fulfill(capacity) in O(N).
  - `3.13.4` Canonical problems: capacity to ship packages within D days, splitting arrays to minimize largest sum.
- **Key Failure Modes & Edge Cases**: Setting improper search range boundaries (low and high) that fail to include the true optimal solution.
- **Verification & Mastery Check**: Calculate the minimum rate limit bucket capacity needed to process a stream of jobs within a fixed deadline.
- **Project Application**: StreamBuffer: Adaptive rate limit capacity tuning.', '{"solution.py": "# Phase 3 // Lesson 3.13: Binary Search on Solution Space\n\ndef solve():\n    \"\"\"\n    Verification: Calculate the minimum rate limit bucket capacity needed to process a stream of jobs within a fixed d\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.13", "subtopics_count": 4, "verification_criteria": "Calculate the minimum rate limit bucket capacity needed to process a stream of jobs within a fixed deadline.", "subtopics": ["3.13.1 Searching without an array: using binary search to find an optimal answer value directly.", "3.13.2 Monotonic condition: if an answer X is possible, all values > X are also possible (or vice versa).", "3.13.3 The feasibility function: a helper function that checks can_fulfill(capacity) in O(N).", "3.13.4 Canonical problems: capacity to ship packages within D days, splitting arrays to minimize largest sum."]}'::jsonb, '["Explain how this implementation prevents: Setting improper search range boundaries (low and high) that fail to include the true optimal solution.", "How does Binary Search on Solution Space scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-14', 'phase-03-lesson-14-recursion-base-cases-call-stack-frames', 'module-5', 14, 'Lesson 5.14: Recursion: Base Cases & Call Stack Frames', 'Prerequisites: Phase 0 (Lesson 0.8)', 'Prerequisites: Phase 0 (Lesson 0.8) | Subtopics: 4 items', 'Systems project application', 160, 4, 870.0, 700.0, '# Lesson 3.14: Recursion: Base Cases & Call Stack Frames

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0 (Lesson 0.8)
- **Subtopics**:
  - `3.14.1` What is recursion: a function that solves a problem by calling itself on smaller sub-problems.
  - `3.14.2` The two essential parts: the Base Case (when to stop) and the Recursive Case (the step forward).
  - `3.14.3` The Call Stack: how Python allocates a new stack frame in memory for every recursive invocation.
  - `3.14.4` Recursion depth limits: understanding why Python stops at 1,000 nested calls to prevent stack overflow.
- **Key Failure Modes & Edge Cases**: Omitting or incorrectly defining the base case, triggering RecursionError: maximum recursion depth exceeded.
- **Verification & Mastery Check**: Write a recursive function that reverses a string and visualize its call stack frames on paper.
- **Project Application**: StreamBuffer: Recursive document parsing.', '{"solution.py": "# Phase 3 // Lesson 3.14: Recursion: Base Cases & Call Stack Frames\n\ndef solve():\n    \"\"\"\n    Verification: Write a recursive function that reverses a string and visualize its call stack frames on paper.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.14", "subtopics_count": 4, "verification_criteria": "Write a recursive function that reverses a string and visualize its call stack frames on paper.", "subtopics": ["3.14.1 What is recursion: a function that solves a problem by calling itself on smaller sub-problems.", "3.14.2 The two essential parts: the Base Case (when to stop) and the Recursive Case (the step forward).", "3.14.3 The Call Stack: how Python allocates a new stack frame in memory for every recursive invocation.", "3.14.4 Recursion depth limits: understanding why Python stops at 1,000 nested calls to prevent stack overflow."]}'::jsonb, '["Explain how this implementation prevents: Omitting or incorrectly defining the base case, triggering RecursionError: maximum recursion depth exceeded.", "How does Recursion: Base Cases & Call Stack Frames scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-15', 'phase-03-lesson-15-tree-traversals-pre-order-in-order-post-o', 'module-5', 15, 'Lesson 5.15: Tree Traversals: Pre-Order, In-Order, Post-Order', 'Prerequisites: Lesson 3.14', 'Prerequisites: Lesson 3.14 | Subtopics: 5 items', 'Systems project application', 160, 4, 750.0, 750.0, '# Lesson 3.15: Tree Traversals: Pre-Order, In-Order, Post-Order

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 3.14
- **Subtopics**:
  - `3.15.1` Hierarchical data structures: trees composed of root, child nodes, and leaves.
  - `3.15.2` Binary trees: trees where each node has at most two children (left and right).
  - `3.15.3` Pre-Order traversal (Root, Left, Right): useful for copying or serializing trees.
  - `3.15.4` In-Order traversal (Left, Root, Right): visiting sorted binary search trees in ascending numerical order.
  - `3.15.5` Post-Order traversal (Left, Right, Root): useful for deleting trees or calculating bottom-up sizes.
- **Key Failure Modes & Edge Cases**: Failing to check if current node is None before attempting to access node.left or node.right.
- **Verification & Mastery Check**: Construct a simple 5-node binary tree and implement all three depth-first traversal orders.
- **Project Application**: StreamBuffer: AST node traversal.', '{"solution.py": "# Phase 3 // Lesson 3.15: Tree Traversals: Pre-Order, In-Order, Post-Order\n\ndef solve():\n    \"\"\"\n    Verification: Construct a simple 5-node binary tree and implement all three depth-first traversal orders.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.15", "subtopics_count": 5, "verification_criteria": "Construct a simple 5-node binary tree and implement all three depth-first traversal orders.", "subtopics": ["3.15.1 Hierarchical data structures: trees composed of root, child nodes, and leaves.", "3.15.2 Binary trees: trees where each node has at most two children (left and right).", "3.15.3 Pre-Order traversal (Root, Left, Right): useful for copying or serializing trees.", "3.15.4 In-Order traversal (Left, Root, Right): visiting sorted binary search trees in ascending numerical order.", "3.15.5 Post-Order traversal (Left, Right, Root): useful for deleting trees or calculating bottom-up sizes."]}'::jsonb, '["Explain how this implementation prevents: Failing to check if current node is None before attempting to access node.left or node.right.", "How does Tree Traversals: Pre-Order, In-Order, Post-Order scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-16', 'phase-03-lesson-16-breadth-first-search-bfs-with-queues', 'module-5', 16, 'Lesson 5.16: Breadth-First Search (BFS) with Queues', 'Prerequisites: Lesson 3.15', 'Prerequisites: Lesson 3.15 | Subtopics: 4 items', 'Systems project application', 160, 4, 810.0, 800.0, '# Lesson 3.16: Breadth-First Search (BFS) with Queues

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 3.15
- **Subtopics**:
  - `3.16.1` Level-by-level exploration: visiting all immediate neighbors before moving to the next depth tier.
  - `3.16.2` The Queue data structure (FIFO): using collections.deque for fast popleft() operations.
  - `3.16.3` Shortest path guarantee: why BFS is mathematically guaranteed to find the shortest path in unweighted graphs.
  - `3.16.4` Tracking visited nodes: preventing infinite loops when graphs contain cycles.
- **Key Failure Modes & Edge Cases**: Using a Python list as a queue and calling pop(0), which is an O(N) memory shift instead of O(1).
- **Verification & Mastery Check**: Implement BFS on a maze grid to find the shortest path from start to goal coordinates.
- **Project Application**: StreamBuffer: Shortest path routing.', '{"solution.py": "# Phase 3 // Lesson 3.16: Breadth-First Search (BFS) with Queues\n\ndef solve():\n    \"\"\"\n    Verification: Implement BFS on a maze grid to find the shortest path from start to goal coordinates.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.16", "subtopics_count": 4, "verification_criteria": "Implement BFS on a maze grid to find the shortest path from start to goal coordinates.", "subtopics": ["3.16.1 Level-by-level exploration: visiting all immediate neighbors before moving to the next depth tier.", "3.16.2 The Queue data structure (FIFO): using collections.deque for fast popleft() operations.", "3.16.3 Shortest path guarantee: why BFS is mathematically guaranteed to find the shortest path in unweighted graphs.", "3.16.4 Tracking visited nodes: preventing infinite loops when graphs contain cycles."]}'::jsonb, '["Explain how this implementation prevents: Using a Python list as a queue and calling pop(0), which is an O(N) memory shift instead of O(1).", "How does Breadth-First Search (BFS) with Queues scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-17', 'phase-03-lesson-17-depth-first-search-dfs-with-stacks', 'module-5', 17, 'Lesson 5.17: Depth-First Search (DFS) with Stacks', 'Prerequisites: Lesson 3.14, Lesson 3.15', 'Prerequisites: Lesson 3.14, Lesson 3.15 | Subtopics: 4 items', 'Systems project application', 160, 4, 870.0, 850.0, '# Lesson 3.17: Depth-First Search (DFS) with Stacks

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 3.14, Lesson 3.15
- **Subtopics**:
  - `3.17.1` Exploring as deep as possible before backtracking: the Depth-First Search strategy.
  - `3.17.2` DFS using recursion: utilizing the call stack implicitly.
  - `3.17.3` Iterative DFS: using an explicit Stack data structure (LIFO) with while stack:.
  - `3.17.4` Applications: finding connected components, detecting cycles, and path existence queries.
- **Key Failure Modes & Edge Cases**: Allowing DFS to run on graphs with cycles without a visited set, leading to stack overflow crashes.
- **Verification & Mastery Check**: Implement iterative DFS using a Python list as a stack to verify reachability between two system nodes.
- **Project Application**: StreamBuffer: Graph connectivity exploration.', '{"solution.py": "# Phase 3 // Lesson 3.17: Depth-First Search (DFS) with Stacks\n\ndef solve():\n    \"\"\"\n    Verification: Implement iterative DFS using a Python list as a stack to verify reachability between two system nod\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.17", "subtopics_count": 4, "verification_criteria": "Implement iterative DFS using a Python list as a stack to verify reachability between two system nodes.", "subtopics": ["3.17.1 Exploring as deep as possible before backtracking: the Depth-First Search strategy.", "3.17.2 DFS using recursion: utilizing the call stack implicitly.", "3.17.3 Iterative DFS: using an explicit Stack data structure (LIFO) with while stack:.", "3.17.4 Applications: finding connected components, detecting cycles, and path existence queries."]}'::jsonb, '["Explain how this implementation prevents: Allowing DFS to run on graphs with cycles without a visited set, leading to stack overflow crashes.", "How does Depth-First Search (DFS) with Stacks scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-18', 'phase-03-lesson-18-topological-sorting-course-prerequisites', 'module-5', 18, 'Lesson 5.18: Topological Sorting: Course Prerequisites', 'Prerequisites: Lesson 3.16, Lesson 3.17', 'Prerequisites: Lesson 3.16, Lesson 3.17 | Subtopics: 4 items', 'Systems project application', 160, 4, 750.0, 900.0, '# Lesson 3.18: Topological Sorting: Course Prerequisites

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 3.16, Lesson 3.17
- **Subtopics**:
  - `3.18.1` Directed Acyclic Graphs (DAGs): directed networks without circular dependency loops.
  - `3.18.2` Topological order: a linear ordering of vertices such that every directed edge u -> v comes before v.
  - `3.18.3` Kahn''s Algorithm: tracking in-degrees (number of incoming prerequisites) and processing 0-in-degree nodes.
  - `3.18.4` Detecting impossible cyclic dependencies: when not all nodes can be processed (e.g. A needs B, B needs A).
- **Key Failure Modes & Edge Cases**: Attempting to topologically sort a graph that contains a cycle, causing dependency resolution deadlock.
- **Verification & Mastery Check**: Given a list of tasks with prerequisites, compute a valid build order or raise an error if a circular cycle exists.
- **Project Application**: StreamBuffer: Build dependency ordering.', '{"solution.py": "# Phase 3 // Lesson 3.18: Topological Sorting: Course Prerequisites\n\ndef solve():\n    \"\"\"\n    Verification: Given a list of tasks with prerequisites, compute a valid build order or raise an error if a circula\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.18", "subtopics_count": 4, "verification_criteria": "Given a list of tasks with prerequisites, compute a valid build order or raise an error if a circular cycle exists.", "subtopics": ["3.18.1 Directed Acyclic Graphs (DAGs): directed networks without circular dependency loops.", "3.18.2 Topological order: a linear ordering of vertices such that every directed edge u -> v comes before v.", "3.18.3 Kahn''s Algorithm: tracking in-degrees (number of incoming prerequisites) and processing 0-in-degree nodes.", "3.18.4 Detecting impossible cyclic dependencies: when not all nodes can be processed (e.g. A needs B, B needs A)."]}'::jsonb, '["Explain how this implementation prevents: Attempting to topologically sort a graph that contains a cycle, causing dependency resolution deadlock.", "How does Topological Sorting: Course Prerequisites scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-19', 'phase-03-lesson-19-hash-collisions-hash-table-chaining', 'module-5', 19, 'Lesson 5.19: Hash Collisions & Hash Table Chaining', 'Prerequisites: Phase 0 (Lesson 0.13), Lesson 3.2', 'Prerequisites: Phase 0 (Lesson 0.13), Lesson 3.2 | Subtopics: 4 items', 'Systems project application', 160, 4, 810.0, 950.0, '# Lesson 3.19: Hash Collisions & Hash Table Chaining

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0 (Lesson 0.13), Lesson 3.2
- **Subtopics**:
  - `3.19.1` How hash tables work: converting arbitrary keys into array bucket indices using a hash function.
  - `3.19.2` The Pigeonhole Principle: why multiple different keys will eventually hash to the exact same bucket.
  - `3.19.3` Separate Chaining: storing collided keys in a linked list or small array inside the bucket.
  - `3.19.4` Load factor: when to resize the underlying bucket array to maintain O(1) average lookup performance.
- **Key Failure Modes & Edge Cases**: Writing a poor hash function that maps all keys to bucket 0, degrading hash map performance to O(N).
- **Verification & Mastery Check**: Build a simplified hash map in Python with 10 buckets that handles collisions via separate chaining.
- **Project Application**: StreamBuffer: Custom hash storage engines.', '{"solution.py": "# Phase 3 // Lesson 3.19: Hash Collisions & Hash Table Chaining\n\ndef solve():\n    \"\"\"\n    Verification: Build a simplified hash map in Python with 10 buckets that handles collisions via separate chaining.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.19", "subtopics_count": 4, "verification_criteria": "Build a simplified hash map in Python with 10 buckets that handles collisions via separate chaining.", "subtopics": ["3.19.1 How hash tables work: converting arbitrary keys into array bucket indices using a hash function.", "3.19.2 The Pigeonhole Principle: why multiple different keys will eventually hash to the exact same bucket.", "3.19.3 Separate Chaining: storing collided keys in a linked list or small array inside the bucket.", "3.19.4 Load factor: when to resize the underlying bucket array to maintain O(1) average lookup performance."]}'::jsonb, '["Explain how this implementation prevents: Writing a poor hash function that maps all keys to bucket 0, degrading hash map performance to O(N).", "How does Hash Collisions & Hash Table Chaining scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-3-20', 'phase-03-lesson-20-stack-applications-valid-parentheses-chec', 'module-5', 20, 'Lesson 5.20: Stack Applications: Valid Parentheses Checking', 'Prerequisites: Lesson 3.2', 'Prerequisites: Lesson 3.2 | Subtopics: 4 items', 'Systems project application', 160, 4, 870.0, 1000.0, '# Lesson 3.20: Stack Applications: Valid Parentheses Checking

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 3.2
- **Subtopics**:
  - `3.20.1` The Stack LIFO principle (Last In, First Out): pushing items on top and popping from the top.
  - `3.20.2` Matching nested structures: opening brackets push, closing brackets pop and verify match.
  - `3.20.3` Checking balanced brackets: verifying (), [], and {} in code, JSON, and math expressions.
  - `3.20.4` Handling mismatched, unclosed, or premature closing brackets.
- **Key Failure Modes & Edge Cases**: Popping from an empty stack when encountering an unexpected closing bracket at the start of input.
- **Verification & Mastery Check**: Implement a syntax validator that checks if nested brackets in an input string are properly matched.
- **Project Application**: StreamBuffer: Code and JSON bracket validator.', '{"solution.py": "# Phase 3 // Lesson 3.20: Stack Applications: Valid Parentheses Checking\n\ndef solve():\n    \"\"\"\n    Verification: Implement a syntax validator that checks if nested brackets in an input string are properly matched.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "3.20", "subtopics_count": 4, "verification_criteria": "Implement a syntax validator that checks if nested brackets in an input string are properly matched.", "subtopics": ["3.20.1 The Stack LIFO principle (Last In, First Out): pushing items on top and popping from the top.", "3.20.2 Matching nested structures: opening brackets push, closing brackets pop and verify match.", "3.20.3 Checking balanced brackets: verifying (), [], and {} in code, JSON, and math expressions.", "3.20.4 Handling mismatched, unclosed, or premature closing brackets."]}'::jsonb, '["Explain how this implementation prevents: Popping from an empty stack when encountering an unexpected closing bracket at the start of input.", "How does Stack Applications: Valid Parentheses Checking scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb)
